include <robotics.scad>
// Ovonic O-120C-5000-6S1P-EC5 shrink-wrapped pack body. Nominal envelope from Ovonic spec list:
// L 156 (±5) x W 44 (±2) x H 48 (±2) mm. Origin: base centre, z up; lead end toward +X.
L = 156; W = 44; H = 48;
r = 3;   // edge radius NOT dimensioned by Ovonic; kept small/conservative so the envelope stays full
cuboid([L, W, H], rounding = r, anchor = BOT, $fn = 32);
